CREATE TABLE IF NOT EXISTS accounts(id INTEGER PRIMARY KEY, email TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, display_name TEXT NOT NULL, role TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(id INTEGER PRIMARY KEY, token_hash TEXT NOT NULL UNIQUE, account_id INTEGER NOT NULL REFERENCES accounts(id), expires_at TEXT NOT NULL, revoked_at TEXT, created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS sessions_account_idx ON sessions(account_id,expires_at);
CREATE TABLE IF NOT EXISTS guardians(id INTEGER PRIMARY KEY, account_id INTEGER NOT NULL UNIQUE REFERENCES accounts(id), phone TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS students(id INTEGER PRIMARY KEY, guardian_id INTEGER NOT NULL REFERENCES guardians(id), name TEXT NOT NULL, birth_date TEXT NOT NULL, shoe_size TEXT NOT NULL, helmet_size TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS students_guardian_idx ON students(guardian_id,name);
CREATE TABLE IF NOT EXISTS guardian_consents(id INTEGER PRIMARY KEY, student_id INTEGER NOT NULL REFERENCES students(id), guardian_id INTEGER NOT NULL REFERENCES guardians(id), scope TEXT NOT NULL, granted_at TEXT NOT NULL, expires_at TEXT NOT NULL, revoked_at TEXT, UNIQUE(student_id,scope,granted_at));
CREATE TABLE IF NOT EXISTS coaches(id INTEGER PRIMARY KEY, account_id INTEGER NOT NULL UNIQUE REFERENCES accounts(id), emergency_phone TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS coach_qualifications(id INTEGER PRIMARY KEY, coach_id INTEGER NOT NULL REFERENCES coaches(id), sport TEXT NOT NULL, level INTEGER NOT NULL, valid_from TEXT NOT NULL, valid_until TEXT NOT NULL, status TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, UNIQUE(coach_id,sport,level,valid_from));
CREATE INDEX IF NOT EXISTS qualification_validity_idx ON coach_qualifications(coach_id,sport,status,valid_until);
CREATE TABLE IF NOT EXISTS course_templates(id INTEGER PRIMARY KEY, name TEXT NOT NULL, sport TEXT NOT NULL, level INTEGER NOT NULL, minimum_age INTEGER NOT NULL, capacity INTEGER NOT NULL CHECK(capacity>0), coach_ratio INTEGER NOT NULL CHECK(coach_ratio>0), required_certification TEXT NOT NULL DEFAULT '', UNIQUE(sport,level,name));
CREATE TABLE IF NOT EXISTS course_prerequisites(id INTEGER PRIMARY KEY, template_id INTEGER NOT NULL REFERENCES course_templates(id), required_sport TEXT NOT NULL, required_level INTEGER NOT NULL, UNIQUE(template_id,required_sport,required_level));
CREATE TABLE IF NOT EXISTS course_sessions(id INTEGER PRIMARY KEY, template_id INTEGER NOT NULL REFERENCES course_templates(id), coach_id INTEGER NOT NULL REFERENCES coaches(id), starts_at TEXT NOT NULL, ends_at TEXT NOT NULL, status TEXT NOT NULL, capacity INTEGER NOT NULL, enrolled INTEGER NOT NULL DEFAULT 0, version INTEGER NOT NULL DEFAULT 1, cancel_reason TEXT NOT NULL DEFAULT '');
CREATE INDEX IF NOT EXISTS course_session_schedule_idx ON course_sessions(coach_id,starts_at,ends_at,status);
CREATE TABLE IF NOT EXISTS enrollments(id INTEGER PRIMARY KEY, session_id INTEGER NOT NULL REFERENCES course_sessions(id), student_id INTEGER NOT NULL REFERENCES students(id), status TEXT NOT NULL, idempotency_key TEXT NOT NULL UNIQUE, version INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL, UNIQUE(session_id,student_id));
CREATE INDEX IF NOT EXISTS enrollment_student_idx ON enrollments(student_id,status);
CREATE TABLE IF NOT EXISTS training_groups(id INTEGER PRIMARY KEY, session_id INTEGER NOT NULL REFERENCES course_sessions(id), coach_id INTEGER NOT NULL REFERENCES coaches(id), name TEXT NOT NULL, capacity INTEGER NOT NULL, version INTEGER NOT NULL DEFAULT 1, UNIQUE(session_id,name));
CREATE TABLE IF NOT EXISTS group_members(id INTEGER PRIMARY KEY, group_id INTEGER NOT NULL REFERENCES training_groups(id), enrollment_id INTEGER NOT NULL UNIQUE REFERENCES enrollments(id), assigned_at TEXT NOT NULL);
